CREATE TABLE IF NOT EXISTS duranki_migration_run (id CHAR(64) PRIMARY KEY, source_created_at VARCHAR(40) NOT NULL, status ENUM('STAGED','VERIFIED') NOT NULL, manifest_json LONGTEXT NOT NULL CHECK (JSON_VALID(manifest_json)), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_migration_file (run_id CHAR(64) NOT NULL, ordinal INT UNSIGNED NOT NULL, source_path VARCHAR(512) NOT NULL, byte_length BIGINT UNSIGNED NOT NULL, sha256 CHAR(64) NOT NULL, PRIMARY KEY(run_id,ordinal), UNIQUE KEY migration_path(run_id,source_path), FOREIGN KEY(run_id) REFERENCES duranki_migration_run(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_migration_chunk (run_id CHAR(64) NOT NULL, file_ordinal INT UNSIGNED NOT NULL, chunk_ordinal INT UNSIGNED NOT NULL, contents MEDIUMBLOB NOT NULL, PRIMARY KEY(run_id,file_ordinal,chunk_ordinal), FOREIGN KEY(run_id,file_ordinal) REFERENCES duranki_migration_file(run_id,ordinal) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_migration_record (run_id CHAR(64) NOT NULL, collection_name VARCHAR(128) NOT NULL, ordinal INT UNSIGNED NOT NULL, payload LONGTEXT NOT NULL CHECK (JSON_VALID(payload)), sha256 CHAR(64) NOT NULL, PRIMARY KEY(run_id,collection_name,ordinal), FOREIGN KEY(run_id) REFERENCES duranki_migration_run(id) ON DELETE RESTRICT) ENGINE=InnoDB;
